def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    patterns = []
    for r in sorted({0, h - 1}):
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            patterns.append(grid[r][start:c])
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value == 0 or r in (0, h - 1):
                continue
            pattern = next((p for p in patterns if value in p), None)
            if pattern is None:
                continue
            start = c - pattern.index(value)
            for i, color in enumerate(pattern):
                x = start + i
                if 0 <= x < w:
                    out[r][x] = color
    return out
